<?= $this->extend('pos/layout') ?><?= $this->section('content') ?>
<section class="panel form-panel"><form method="post" enctype="multipart/form-data" action="<?= site_url($entity.'/save') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= esc($row['id']??'') ?>">
<?php $fields=match($entity){'products'=>['name'=>['Product name','text',100],'price'=>['Unit price (PHP)','number',null],'stock_quantity'=>['Stock quantity','number',null]],'customers'=>['full_name'=>['Full name','text',100],'email'=>['Email address','email',100],'phone'=>['Phone (optional)','tel',20]],'users'=>['full_name'=>['Full name','text',100],'username'=>['Username','text',50],'password'=>[isset($row['id'])?'New password (leave blank to keep current)':'Password','password',72]]}; foreach($fields as $key=>[$label,$type,$max]): ?><label><?= esc($label) ?><input type="<?= $type ?>" name="<?= $key ?>" value="<?= $key==='password'?'':esc(old($key,$row[$key]??'')) ?>" <?= !in_array($key,['phone','password'])||($key==='password'&&!isset($row['id']))?'required':'' ?> <?= $max?'maxlength="'.$max.'"':'' ?> <?= $type==='number'?'min="0" step="'.($key==='price'?'0.01':'1').'"':'' ?> <?= $key==='password'?'minlength="10" autocomplete="new-password"':'' ?>></label><?php endforeach ?>
<?php if($entity!=='customers'): $key=$entity==='products'?'image':'avatar'; ?><label><?= $entity==='products'?'Product image':'Staff avatar' ?> <?= isset($row['id'])?'(optional replacement)':'(optional)' ?><input type="file" name="<?= $key ?>" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP · Up to 2 MB · Resized to 800 px and safely re-encoded as JPEG.</small></label><?php if(!empty($row[$key])): ?><img class="preview" src="<?= site_url('media/'.$row[$key]) ?>" alt="Current image"><?php endif ?><?php endif ?>
<div class="actions"><button>Save changes</button><a class="button secondary" href="<?= site_url($entity) ?>">Cancel</a></div></form></section>
<?= $this->endSection() ?>
